// mKOBO — textes : une seule table (fr, en, es, it), clés identiques dans les quatre langues, aucun texte visible en dur dans le code.
import Foundation

enum L {
    enum Lang: Int { case fr = 0, en, es, it }
    static let lang: Lang = {
        func lang(_ c: String) -> Lang? { switch c { case "fr": .fr; case "en": .en; case "es": .es; case "it": .it; default: nil } }
        if let forced = ProcessInfo.processInfo.environment["MKOBO_LANG"] { return lang(forced) ?? .en }
        // Première langue préférée du Mac qui fait partie des quatre, sinon l'anglais.
        return Locale.preferredLanguages.lazy.compactMap { lang(String($0.prefix(2))) }.first ?? .en
    }()
    static var code: String { ["fr", "en", "es", "it"][lang.rawValue] }

    static func t(_ key: String, _ args: CVarArg...) -> String {
        guard let row = table[key] else { return key }
        let s = row[lang.rawValue]
        return args.isEmpty ? s : String(format: s, arguments: args)
    }

    /// Clés dont une langue manque (tests/check_l10n.sh).
    static func problems() -> [String] { table.filter { $0.value.count != 4 || $0.value.contains(where: { $0.isEmpty }) }.map(\.key).sorted() }

